// Input: one item per week from the Weekly KPIs node, newest week first
const weeks = $input.all().map(item => item.json);

// A week is "final" once most of its orders have been delivered;
// before that, delivery metrics look better than they really are.
const FINAL_SHARE = 80;
const finalWeeks = weeks.filter(w => Number(w.delivered_share_pct) >= FINAL_SHARE);

const latest = weeks[0];                    // newest week (may not be final yet)
const latestFinal = finalWeeks[0];          // newest week that can be fully judged
const baselineWeeks = finalWeeks.slice(1);  // older final weeks = the normal level

// Average of one column over several weeks
const avg = (rows, key) =>
  rows.reduce((sum, r) => sum + Number(r[key]), 0) / rows.length;

const alerts = [];

// 1. Volume and cancellations are known as soon as orders are placed
if (Number(latest.orders) < 50) {
  alerts.push(`Low order volume in week ${latest.week_start}: ${latest.orders} orders`);
}
if (Number(latest.cancel_rate_pct) > 5) {
  alerts.push(`High cancellation rate in week ${latest.week_start}: ${latest.cancel_rate_pct}%`);
}

// 2. Delivery metrics: compare the latest final week with the older final weeks
if (latestFinal && baselineWeeks.length > 0) {
  const baseLate = avg(baselineWeeks, 'late_rate_pct');
  const baseSeller = avg(baselineWeeks, 'avg_seller_handling_days');
  const baseCarrier = avg(baselineWeeks, 'avg_carrier_transit_days');

  if (Number(latestFinal.late_rate_pct) > baseLate + 5) {
    alerts.push(`Late deliveries up in week ${latestFinal.week_start}: ${latestFinal.late_rate_pct}% vs ${baseLate.toFixed(1)}% normally`);
  }
  if (Number(latestFinal.avg_seller_handling_days) > baseSeller + 2) {
    alerts.push(`Sellers slower in week ${latestFinal.week_start}: ${latestFinal.avg_seller_handling_days} days vs ${baseSeller.toFixed(1)} normally`);
  }
  if (Number(latestFinal.avg_carrier_transit_days) > baseCarrier + 3) {
    alerts.push(`Carriers slower in week ${latestFinal.week_start}: ${latestFinal.avg_carrier_transit_days} days vs ${baseCarrier.toFixed(1)} normally`);
  }
}

return [{
  json: {
    latest_week: latest.week_start,
    latest_final_week: latestFinal ? latestFinal.week_start : null,
    has_alerts: alerts.length > 0,
    alerts,
    weeks,
  },
}];

